import { NextRequest } from "next/server";
import { putBlob } from "@/app/lib/blobStore";
import { assessMatch, placeTokens, unwrapUrl } from "@/app/lib/matchAnalysis";
import { resolveOrigin } from "@/app/lib/origin";
import { parseRent } from "@/app/lib/money";
import { fetchListing, parseListing, type Listing } from "@/app/lib/scrape";
import { grade, type ImageMatch } from "@/app/lib/verdict";
import { reverseImageSearch } from "@/app/lib/zenserp";
import type { IAnalysis, ITrace } from "@/interfaces/analysis.interface";

export const dynamic = "force-dynamic";

/**
 * A reverse image search takes ~30s, so the default serverless ceiling is not
 * enough. Hosts that honour this (Vercel) will allow the full analysis.
 */
export const maxDuration = 120;

/** The extension popup runs on a chrome-extension:// origin, so it needs CORS. */
const CORS = {
  "access-control-allow-origin": "*",
  "access-control-allow-headers": "content-type",
  "access-control-allow-methods": "POST, OPTIONS",
};

export async function OPTIONS() {
  return new Response(null, { status: 204, headers: CORS });
}

/**
 * Reverse image search is the expensive part — one Zenserp call per photo — so
 * only the first few are checked. Listing galleries repeat the same rooms, and
 * a scammer who lifted one picture lifted the set.
 */
const MAX_IMAGES_TO_SEARCH = 4;

const BLOCKED_HOST = /^(localhost|127\.|0\.0\.0\.0|\[?::1\]?|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/i;

/** What the extension sends after reading the page in the user's browser. */
type ScrapedPayload = {
  url: string;
  title?: string | null;
  price?: string | null;
  address?: string | null;
  description?: string | null;
  images?: string[];
};

const MAX_UPLOAD_BYTES = 12 * 1024 * 1024;

/** Build a listing out of what the user typed, when scraping is impossible. */
function manualListing(form: FormData, images: string[]): Listing {
  const str = (k: string) => {
    const v = form.get(k);
    return typeof v === "string" && v.trim() ? v.trim() : null;
  };
  const sourceUrl = str("sourceUrl");
  let host = "uploaded-photos";
  if (sourceUrl) {
    try {
      host = new URL(sourceUrl.startsWith("http") ? sourceUrl : `https://${sourceUrl}`).host;
    } catch {
      /* a malformed reference URL just means we can't exclude its own hits */
    }
  }
  return {
    url: sourceUrl ?? "",
    host,
    title: str("title"),
    price: str("price"),
    currency: null,
    address: str("address"),
    description: null,
    images,
    emails: [],
    phones: [],
    siteName: null,
    via: ["entered by hand"],
  };
}

export async function POST(request: NextRequest) {
  const traces: ITrace[] = [];
  let listing: Listing;

  const contentType = request.headers.get("content-type") ?? "";

  if (contentType.includes("multipart/form-data")) {
    // Upload path. Plenty of portals block automated requests outright, so the
    // photos can be handed over directly instead of being scraped.
    const form = await request.formData();
    const files = form.getAll("photos").filter((f): f is File => f instanceof File && f.size > 0);

    if (files.length === 0) {
      return Response.json({ error: "Attach at least one photo from the listing." }, { status: 400, headers: CORS });
    }
    const tooBig = files.find((f) => f.size > MAX_UPLOAD_BYTES);
    if (tooBig) {
      return Response.json(
        { error: `${tooBig.name} is ${(tooBig.size / 1e6).toFixed(1)} MB; the limit is 12 MB per photo.` },
        { status: 413 }
      );
    }

    const origin = resolveOrigin(request);
    if (!origin.publiclyReachable) {
      return Response.json({ error: origin.reason }, { status: 400, headers: CORS });
    }

    const hosted: string[] = [];
    for (const file of files.slice(0, MAX_IMAGES_TO_SEARCH)) {
      const bytes = Buffer.from(await file.arrayBuffer());
      hosted.push(`${origin.origin}/api/image/blob/${putBlob(bytes, file.type || "image/jpeg")}`);
    }

    listing = manualListing(form, hosted);
    traces.push({
      api: "fetch",
      label: `${hosted.length} photo${hosted.length === 1 ? "" : "s"} uploaded`,
      url: listing.url || "(no listing URL given)",
      elapsedMs: null,
      status: null,
      notice: null,
    });
  } else {
    let body: { url?: string; scraped?: ScrapedPayload };
    try {
      body = (await request.json()) as { url?: string; scraped?: ScrapedPayload };
    } catch {
      return Response.json({ error: "Invalid JSON body." }, { status: 400, headers: CORS });
    }

    // The browser extension reads the page the user is already looking at, so
    // the markup arrives already parsed. This is how a portal that refuses
    // server-side requests gets checked at all.
    if (body.scraped) {
      const sc = body.scraped;
      const images = (sc.images ?? [])
        .filter((i) => typeof i === "string" && /^https?:\/\//i.test(i))
        .slice(0, 12);
      if (images.length === 0) {
        return Response.json(
          { error: "No usable photographs were found on that page." },
          { status: 400 }
        );
      }
      let host = "page";
      try {
        host = new URL(sc.url).host;
      } catch {
        /* without a URL we simply can't exclude same-site hits */
      }
      listing = {
        url: sc.url ?? "",
        host,
        title: sc.title ?? null,
        price: sc.price ?? null,
        currency: null,
        address: sc.address ?? null,
        description: sc.description ?? null,
        images,
        emails: [],
        phones: [],
        siteName: null,
        via: ["read in your browser by the extension"],
      };
      traces.push({
        api: "fetch",
        label: "Page read by the browser extension",
        url: sc.url ?? "(no URL)",
        elapsedMs: null,
        status: 200,
        notice: null,
      });
      return analyse(listing, traces);
    }

    const raw = body.url?.trim();
    if (!raw) return Response.json({ error: "Paste a rental listing URL." }, { status: 400, headers: CORS });

    let target: URL;
    try {
      target = new URL(raw.startsWith("http") ? raw : `https://${raw}`);
    } catch {
      return Response.json({ error: `"${raw}" is not a valid URL.` }, { status: 400 });
    }
    if (target.protocol !== "http:" && target.protocol !== "https:") {
      return Response.json({ error: "Only http and https URLs are supported." }, { status: 400, headers: CORS });
    }
    if (BLOCKED_HOST.test(target.hostname)) {
      return Response.json({ error: "That address is not reachable from here." }, { status: 400, headers: CORS });
    }

    const page = await fetchListing(target.toString());
    if (!page.ok) {
      return Response.json(
        { error: page.error, blocked: page.status === 403 || page.status === 429 },
        { status: 502, headers: CORS }
      );
    }
    traces.push({
      api: "fetch",
      label: "Fetch listing page",
      url: target.toString(),
      elapsedMs: page.elapsedMs,
      status: 200,
      notice: null,
    });

    listing = parseListing(page.html, page.finalUrl);
  }

  return analyse(listing, traces);
}

/** Search the photographs and grade what comes back. */
async function analyse(listing: Listing, traces: ITrace[]) {
  const toSearch = listing.images.slice(0, MAX_IMAGES_TO_SEARCH);

  // Compared against every match, so parse them once rather than per result.
  const listingRent = parseRent(`${listing.price ?? ""} ${listing.title ?? ""}`);
  const listingPlaces = placeTokens(`${listing.address ?? ""} ${listing.title ?? ""}`);

  // Concurrently: these are independent lookups, and run back to back they add
  // up to minutes rather than seconds.
  const matches: ImageMatch[] = await Promise.all(
    toSearch.map(async (imageUrl) => {
      const res = await reverseImageSearch(imageUrl, 20);
      traces.push({
        api: "zenserp",
        label: `Reverse image search — ${imageUrl.split("/").pop()?.slice(0, 40)}`,
        url: res.maskedUrl,
        elapsedMs: res.elapsedMs,
        status: res.status,
        notice: res.notice,
      });

      const elsewhere = [];
      let sameSite = 0;

      for (const hit of res.data ?? []) {
        const { host } = unwrapUrl(hit.url);
        if (host.replace(/^www\./, "") === listing.host.replace(/^www\./, "")) {
          sameSite++;
          continue;
        }
        elsewhere.push(assessMatch(listing, hit, listingRent, listingPlaces));
      }

      return { imageUrl, elsewhere, sameSite, notice: res.notice };
    })
  );

  const payload: IAnalysis = {
    listing,
    matches,
    verdict: grade(listing, matches),
    traces,
    skippedImages: Math.max(0, listing.images.length - toSearch.length),
  };
  return Response.json(payload, { headers: { "cache-control": "no-store", ...CORS } });
}

import { NextRequest } from "next/server";
import { BLOB_TTL_MS, getBlob } from "@/app/lib/blobStore";

export const dynamic = "force-dynamic";

/**
 * Serves an uploaded image for exactly as long as a reverse image search needs
 * it. Marked noindex so the temporary URL can't end up in a search index — this
 * is a privacy tool, and the image belongs to whoever uploaded it.
 */
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const entry = getBlob(id);

  if (!entry) {
    return new Response("Not found or expired.", { status: 404 });
  }

  return new Response(new Uint8Array(entry.bytes), {
    headers: {
      "content-type": entry.type,
      "content-length": String(entry.bytes.length),
      "cache-control": `private, max-age=${Math.floor(BLOB_TTL_MS / 1000)}`,
      "x-robots-tag": "noindex, nofollow, noarchive",
    },
  });
}

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
};

export default nextConfig;

import type { Metadata } from "next";
import { IBM_Plex_Mono, IBM_Plex_Sans, IBM_Plex_Serif } from "next/font/google";
import "./globals.css";

/**
 * IBM Plex, not the framework default. Plex was drawn for technical and
 * institutional work, which is the register this tool needs: it is telling
 * someone whether to hand over a deposit. The three cuts are one superfamily,
 * so the serif headlines and the mono data sit together without clashing.
 */
const plexSans = IBM_Plex_Sans({
  variable: "--font-plex-sans",
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
  display: "swap",
});

const plexMono = IBM_Plex_Mono({
  variable: "--font-plex-mono",
  subsets: ["latin"],
  weight: ["400", "500", "600"],
  display: "swap",
});

const plexSerif = IBM_Plex_Serif({
  variable: "--font-plex-serif",
  subsets: ["latin"],
  weight: ["500", "600"],
  display: "swap",
});

export const metadata: Metadata = {
  title: "Rental Scam Detector: check a listing before you pay a deposit",
  description:
    "Paste a rental listing URL. The tool reads the advert, reverse image searches every photo with Zenserp, then compares the price and location on every other page using those same pictures. Cross-posting is normal. The same rooms advertised far cheaper, or somewhere else entirely, is what a rental scam looks like.",
};

export default function RootLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return (
    <html
      lang="en"
      data-theme="dark"
      suppressHydrationWarning
      className={`${plexSans.variable} ${plexMono.variable} ${plexSerif.variable} h-full antialiased`}
    >
      <head>
        <script
          dangerouslySetInnerHTML={{
            __html: `try{var t=localStorage.getItem('rentalscan-theme');if(t==='dark'||t==='light'){document.documentElement.dataset.theme=t;}}catch(e){}`,
          }}
        />
      </head>
      <body className="min-h-full flex flex-col">{children}</body>
    </html>
  );
}

const DEFAULT_API = "http://localhost:3400";

const $ = (id) => document.getElementById(id);
const show = (id) => {
  for (const pane of ["idle", "busy", "result", "failed"]) $(pane).hidden = pane !== id;
};

const STAGES = [
  "Reading the page",
  "Collecting the photographs",
  "Reverse image searching every photo",
  "Still searching. This step drives a real search engine",
  "Weighing up the findings",
];

let stageTimer = null;

async function apiBase() {
  const { apiBase } = await chrome.storage.sync.get("apiBase");
  return (apiBase || DEFAULT_API).replace(/\/$/, "");
}

/* ── Settings ─────────────────────────────────────────────────────────── */
$("settings-toggle").addEventListener("click", async () => {
  const panel = $("settings");
  panel.hidden = !panel.hidden;
  if (!panel.hidden) $("api-base").value = await apiBase();
});

$("api-base").addEventListener("change", (e) => {
  chrome.storage.sync.set({ apiBase: e.target.value.trim() });
});

/* ── Which page are we on ─────────────────────────────────────────────── */
async function currentTab() {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  return tab;
}

currentTab().then((tab) => {
  if (!tab?.url) return;
  try {
    $("page-host").textContent = `This tab: ${new URL(tab.url).host}`;
  } catch {
    /* internal pages have no useful host */
  }
});

/* ── Scan ─────────────────────────────────────────────────────────────── */
async function scan() {
  const tab = await currentTab();
  if (!tab?.id || !/^https?:/.test(tab.url ?? "")) {
    return fail("Open a rental listing in this tab first.");
  }

  show("busy");
  let step = 0;
  $("stage").textContent = STAGES[0];
  stageTimer = setInterval(() => {
    step = Math.min(step + 1, STAGES.length - 1);
    $("stage").textContent = STAGES[step];
  }, 9000);

  try {
    // Read the DOM in the page itself. This is what gets past portals that
    // refuse requests coming from a server.
    const [{ result: scraped }] = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      files: ["scrape.js"],
    });

    if (!scraped?.images?.length) {
      return fail("No usable photographs found on this page.");
    }

    const base = await apiBase();
    const res = await fetch(`${base}/api/analyze`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ scraped }),
    });
    const json = await res.json();
    if (!res.ok) throw new Error(json.error ?? `Request failed (${res.status})`);
    render(json, base);
  } catch (e) {
    const msg = String(e?.message ?? e);
    fail(
      /Failed to fetch|NetworkError/i.test(msg)
        ? `Could not reach the app at ${await apiBase()}. Set the address with the gear icon.`
        : msg
    );
  } finally {
    clearInterval(stageTimer);
  }
}

function fail(message) {
  clearInterval(stageTimer);
  $("error-text").textContent = message;
  show("failed");
}

/* ── Render ───────────────────────────────────────────────────────────── */
const COLOUR = {
  "almost certainly a scam": "var(--danger)",
  "high risk": "var(--danger)",
  "worth checking": "var(--warn)",
  "looks clean": "var(--safe)",
};

function render(data, base) {
  const { verdict, matches, listing } = data;
  const colour = COLOUR[verdict.band] ?? "var(--muted)";

  $("verdict").innerHTML = `
    <div class="score">
      <b style="color:${colour}">${verdict.score}</b>
      <span style="color:${colour}">${esc(verdict.band)}</span>
    </div>
    <p class="headline">${esc(verdict.headline)}</p>`;

  $("findings").innerHTML = verdict.findings
    .map(
      (f) => `
      <div class="finding">
        <div class="finding-top">
          <span class="tag ${f.level}">${esc(f.level)}</span>
          <span class="finding-label">${esc(f.label)}</span>
        </div>
        <p class="finding-detail">${esc(f.detail)}</p>
      </div>`
    )
    .join("");

  // Only the pages that disagree are worth the popup's limited room.
  const conflicting = matches
    .flatMap((m) => m.elsewhere)
    .filter((e) => e.concern !== "none")
    .sort((a, b) => (b.concern === "high" ? 1 : 0) - (a.concern === "high" ? 1 : 0))
    .slice(0, 5);

  $("matches").innerHTML = conflicting.length
    ? `<h3 class="section">Pages that disagree</h3>` +
      conflicting
        .map(
          (e) => `
        <div class="match">
          ${
            e.url
              ? `<a href="${esc(e.url)}" target="_blank" rel="noreferrer">${esc(e.title.slice(0, 80))}</a>`
              : `<span class="title">${esc(e.title.slice(0, 80))}</span>`
          }
          <p class="host">${esc(e.host)}${e.url ? "" : " (no direct link)"}</p>
          <ul>${e.reasons.map((r) => `<li>${esc(r)}</li>`).join("")}</ul>
        </div>`
        )
        .join("")
    : "";

  const full = new URL(base);
  full.searchParams.set("url", listing.url || "");
  $("open-full").href = full.toString();
  show("result");
}

const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]
  );

$("scan").addEventListener("click", scan);
$("retry").addEventListener("click", () => show("idle"));

import type { Listing } from "@/app/lib/scrape";
import type { ImageMatch, Verdict } from "@/app/lib/verdict";

export interface ITrace {
  api: "zenserp" | "fetch";
  label: string;
  url: string;
  elapsedMs: number | null;
  status: number | null;
  notice: string | null;
}

export interface IAnalysis {
  listing: Listing;
  matches: ImageMatch[];
  verdict: Verdict;
  traces: ITrace[];
  /** Images present but not searched, because of the per-request budget. */
  skippedImages: number;
}

export interface IApiError {
  error: string;
}

{
  "manifest_version": 3,
  "name": "Rental Scam Detector",
  "version": "1.0.0",
  "description": "Check the listing you are looking at. Finds where its photos appear elsewhere and whether the price and location agree.",
  "permissions": ["activeTab", "scripting", "storage"],
  "host_permissions": ["http://localhost/*", "https://*/*"],
  "action": {
    "default_popup": "popup.html",
    "default_title": "Check this rental listing",
    "default_icon": {
      "16": "icons/icon-16.png",
      "48": "icons/icon-48.png",
      "128": "icons/icon-128.png"
    }
  },
  "icons": {
    "16": "icons/icon-16.png",
    "48": "icons/icon-48.png",
    "128": "icons/icon-128.png"
  }
}

/**
 * Runs inside the page the user is actually looking at.
 *
 * This is the whole point of the extension: portals that refuse requests from a
 * server will happily render for a signed-in browser, so reading the DOM here
 * gets past the 403 that blocks the web version.
 */
function readListing() {
  const meta = (name) =>
    document.querySelector(`meta[property="${name}"]`)?.content ??
    document.querySelector(`meta[name="${name}"]`)?.content ??
    null;

  const JUNK = /(sprite|icon|logo|wordmark|avatar|placeholder|pixel|blank|1x1|favicon|badge|button|arrow|map-?static|loading|spinner)/i;
  const THUMB = /(\/thumb\/|[/_-]\d{2,3}px-|[?&](w|width)=\d{1,2}\b)/i;

  // Structured data first: most property sites publish it, and it beats guessing.
  let ld = {};
  for (const node of document.querySelectorAll('script[type="application/ld+json"]')) {
    try {
      const flat = [].concat(JSON.parse(node.textContent));
      for (const item of flat) {
        const t = String(item?.["@type"] ?? "");
        if (/Offer|Product|Residence|Apartment|House|RealEstate|Accommodation/i.test(t)) {
          ld = item;
          break;
        }
      }
    } catch {
      /* a malformed block shouldn't stop the scan */
    }
  }

  const seen = new Set();
  const images = [];
  const add = (raw, rank) => {
    if (!raw || !raw.trim()) return;
    let abs;
    try {
      abs = new URL(raw, location.href).href;
    } catch {
      return;
    }
    if (!/^https?:/.test(abs)) return;
    // An <img> with an empty src resolves to the page itself. Searching that
    // burns a 30-second lookup on something that is not a photograph.
    if (abs.split("#")[0] === location.href.split("#")[0]) return;
    if (/\.svg($|\?)/i.test(abs) || JUNK.test(abs) || THUMB.test(abs)) return;
    if (seen.has(abs)) return;
    seen.add(abs);
    images.push({ url: abs, rank });
  };

  if (typeof ld.image === "string") add(ld.image, 0);
  else if (Array.isArray(ld.image)) ld.image.forEach((i) => add(typeof i === "string" ? i : i?.url, 0));
  add(meta("og:image"), 1);

  for (const img of document.images) {
    // Rendered size is the honest test of whether something is a photo.
    if (img.naturalWidth && img.naturalWidth < 300) continue;
    if (img.clientWidth && img.clientWidth < 150) continue;
    add(img.currentSrc || img.src, 2);
  }

  const priceText =
    ld?.offers?.price ??
    meta("product:price:amount") ??
    (document.body.innerText.match(
      /(?:[$£€₦₵¥]|USD|GBP|EUR)\s?[\d,]+(?:\.\d{2})?(?:\s?(?:per|\/)\s?(?:month|mo|week|wk|pcm|pw))?/i
    )?.[0] ?? null);

  const addr = ld?.address;
  // `??` and `||` cannot be mixed without parentheses; doing so is a syntax
  // error, not a precedence quirk, so each fallback is bracketed explicitly.
  const fromParts =
    [addr?.streetAddress, addr?.addressLocality, addr?.addressRegion, addr?.postalCode]
      .filter(Boolean)
      .join(", ") || null;
  const fromMarkup =
    document.querySelector('[class*="address" i]')?.innerText?.trim()?.slice(0, 140) || null;
  const address = (typeof addr === "string" ? addr : null) || fromParts || fromMarkup || null;

  return {
    url: location.href,
    title: ld.name ?? meta("og:title") ?? document.title ?? null,
    price: priceText ? String(priceText) : null,
    address,
    description: (ld.description ?? meta("og:description") ?? "").slice(0, 600) || null,
    images: images.sort((a, b) => a.rank - b.rank).map((i) => i.url).slice(0, 8),
  };
}

readListing();

"use client";

import { useState } from "react";

const STEPS = [
  "Download the zip and unzip it somewhere you will keep it.",
  "Open chrome://extensions and turn on Developer mode, top right.",
  'Click "Load unpacked" and choose the folder you just unzipped.',
  "Open a rental listing, click the icon, then Scan this page.",
];

/**
 * The extension exists because of a specific failure: portals like Trulia return
 * 403 to anything that looks automated, so the server can never read them. A
 * browser the user is already signed into can.
 */
export function ExtensionCallout() {
  const [open, setOpen] = useState(false);

  return (
    <section className="overflow-hidden rounded-xl border border-accent/30 bg-bg-elev">
      <div className="flex flex-wrap items-center justify-between gap-3 p-4">
        <div className="min-w-0">
          <h2 className="display text-base text-fg">Check listings the site will not let us read</h2>
          <p className="mt-1 max-w-xl text-[12px] leading-relaxed text-fg-muted">
            Some portals block automated requests outright. The browser extension
            reads the page you are already looking at, so those listings can be
            checked too. Results appear in the popup.
          </p>
        </div>
        <div className="flex shrink-0 gap-2">
          <a
            href="/rental-scam-detector-extension.zip"
            download
            className="rounded-lg bg-accent px-4 py-2 text-xs font-semibold text-white transition hover:bg-accent-bright"
          >
            Add as extension
          </a>
          <button
            type="button"
            onClick={() => setOpen((o) => !o)}
            className="mono rounded-lg border border-border bg-bg-elev-2 px-3 py-2 text-[11px] text-fg-muted transition hover:text-fg"
            aria-expanded={open}
          >
            {open ? "Hide steps" : "How to install"}
          </button>
        </div>
      </div>

      {open && (
        <ol className="space-y-2 border-t border-border bg-bg-elev-2 px-4 py-4">
          {STEPS.map((s, i) => (
            <li key={s} className="flex gap-3 text-[12px] text-fg-muted">
