import { randomBytes } from "crypto";

type Entry = { bytes: Buffer; type: string; at: number };

/**
 * Short-lived, in-memory home for uploaded images.
 *
 * Zenserp's reverse image search fetches the image itself, so a photo pasted in
 * by hand has to be reachable over HTTP for the length of one search. Nothing is written to
 * disk, ids are unguessable, and entries evict themselves — this is a holding
 * area for a single lookup, not storage.
 */
const TTL_MS = 10 * 60_000;
const MAX_ENTRIES = 40;

const store = new Map<string, Entry>();

function sweep() {
  const cutoff = Date.now() - TTL_MS;
  for (const [id, e] of store) if (e.at < cutoff) store.delete(id);
  // Hard ceiling so a burst of uploads can't grow memory without bound.
  while (store.size > MAX_ENTRIES) {
    const oldest = store.keys().next().value;
    if (!oldest) break;
    store.delete(oldest);
  }
}

export function putBlob(bytes: Buffer, type: string): string {
  sweep();
  const id = randomBytes(16).toString("hex");
  store.set(id, { bytes, type: type || "application/octet-stream", at: Date.now() });
  return id;
}

export function getBlob(id: string): Entry | null {
  sweep();
  return store.get(id) ?? null;
}

export const BLOB_TTL_MS = TTL_MS;

import type { NextRequest } from "next/server";

const PRIVATE_HOST =
  /^(localhost|127\.|0\.0\.0\.0|\[?::1\]?|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|.*\.local)$/i;

export type OriginInfo = {
  origin: string;
  /** Whether a third-party API could actually fetch a URL on this origin. */
  publiclyReachable: boolean;
  reason: string | null;
};

/**
 * Where this app is reachable from the outside. Zenserp has to fetch an
 * uploaded photo over the public internet, so a dev server on localhost cannot
 * be used to check uploads — better to say that plainly than to
 * send an unreachable URL and report an empty result.
 */
export function resolveOrigin(request: NextRequest): OriginInfo {
  const configured = process.env.PUBLIC_ORIGIN?.trim();
  if (configured) {
    return { origin: configured.replace(/\/$/, ""), publiclyReachable: true, reason: null };
  }

  const host =
    request.headers.get("x-forwarded-host") ?? request.headers.get("host") ?? "";
  const proto =
    request.headers.get("x-forwarded-proto") ?? (host.startsWith("localhost") ? "http" : "https");
  const hostname = host.split(":")[0];

  if (!host) {
    return { origin: "", publiclyReachable: false, reason: "Could not determine this app's own URL." };
  }
  if (PRIVATE_HOST.test(hostname)) {
    return {
      origin: `${proto}://${host}`,
      publiclyReachable: false,
      reason:
        "Checking uploaded photos needs a URL the search engine can reach, and this app is running on a private address. Deploy it, or set PUBLIC_ORIGIN to a tunnel URL, to use the upload option.",
    };
  }
  return { origin: `${proto}://${host}`, publiclyReachable: true, reason: null };
}
